dashboard.definition:
{
    "title": "Server, Datenbanken und Virtualisierung",
    "description": "IT-Infrastruktur des SAKH: Server-Performance, Datenbank-KPIs, ESXi-Hosts, Backups und Windows-/Linux-Logs",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_building": {
            "type": "input.dropdown",
            "title": "Haus",
            "options": {
                "items": [
                    {
                        "label": "Alle Haeuser",
                        "value": "*"
                    },
                    {
                        "label": "Haus A - Innere Medizin",
                        "value": "A"
                    },
                    {
                        "label": "Haus B - Chirurgisches Zentrum",
                        "value": "B"
                    },
                    {
                        "label": "Haus C - Akut- und Intensivzentrum",
                        "value": "C"
                    },
                    {
                        "label": "Haus D - Frauen, Kind und Psyche",
                        "value": "D"
                    }
                ],
                "token": "building",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "host": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_srv": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.server.cpu_pct\", \"sakh.server.mem_pct\", \"sakh.server.fs_data_used_pct\", \"sakh.server.iowait_pct\", \"sakh.server.disk_c_free_pct\") building=\"$building$\" BY metric_name host application os_family span=5m",
                "enableSmartSources": true
            },
            "name": "Server-Metriken (5 min)"
        },
        "ds_db": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.db.avg_query_ms\", \"sakh.db.blocked_sessions\", \"sakh.db.active_sessions\", \"sakh.db.tps\", \"sakh.db.replication_lag_s\", \"sakh.db.cpu_pct\") BY metric_name instance engine host span=5m",
                "enableSmartSources": true
            },
            "name": "Datenbank-Metriken (5 min)"
        },
        "ds_k_cpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_srv",
                "query": "| where metric_name=\"sakh.server.cpu_pct\" | timechart span=5m max(v) as \"CPU max\""
            }
        },
        "ds_k_q": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_db",
                "query": "| where metric_name=\"sakh.db.avg_query_ms\" AND instance=\"KISPRD\" | timechart span=5m avg(v) as \"KISPRD Abfrage ms\""
            }
        },
        "ds_k_block": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_db",
                "query": "| where metric_name=\"sakh.db.blocked_sessions\" | timechart span=5m sum(v) as \"Gesperrte Sessions\""
            }
        },
        "ds_k_lag": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_db",
                "query": "| where metric_name=\"sakh.db.replication_lag_s\" AND instance=\"KISSTBY\" | timechart span=5m avg(v) as \"Data Guard Lag s\""
            }
        },
        "ds_k_esx": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name=\"sakh.vmware.cpu_pct\" span=5m | rename v as \"ESXi CPU\"",
                "enableSmartSources": true
            }
        },
        "ds_k_bkp": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:backup\" status=\"Failed\" earliest=-24h | stats count as \"Backups fehlgeschlagen\"",
                "enableSmartSources": true
            }
        },
        "ds_heat_cpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_srv",
                "query": "| where metric_name=\"sakh.server.cpu_pct\" | timechart span=5m limit=0 avg(v) by host"
            }
        },
        "ds_fs": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_srv",
                "query": "| where metric_name=\"sakh.server.fs_data_used_pct\" | timechart span=5m limit=0 max(v) by host"
            }
        },
        "ds_host": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.server.cpu_pct\", \"sakh.server.mem_pct\", \"sakh.server.iowait_pct\", \"sakh.server.fs_data_used_pct\") host=\"$host$\" BY metric_name span=5m\n| eval series=replace(metric_name, \"sakh.server.\", \"\") | timechart span=5m avg(v) by series",
                "enableSmartSources": true
            }
        },
        "ds_db_q": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_db",
                "query": "| where metric_name=\"sakh.db.avg_query_ms\" | timechart span=5m avg(v) by instance"
            }
        },
        "ds_db_block": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_db",
                "query": "| where metric_name IN (\"sakh.db.blocked_sessions\", \"sakh.db.active_sessions\") AND instance=\"KISPRD\" | eval series=if(metric_name=\"sakh.db.blocked_sessions\", \"gesperrt\", \"aktiv\") | timechart span=5m avg(v) by series"
            }
        },
        "ds_db_table": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:db:performance\" earliest=-10m\n| stats latest(engine) as Engine latest(version) as Version latest(host) as Host latest(application) as Anwendung latest(avg_query_ms) as \"Abfrage ms\" latest(active_sessions) as Sessions latest(blocked_sessions) as Gesperrt latest(top_wait_event) as \"Top Wait\" latest(replication_lag_s) as \"Lag s\" latest(status) as Status by instance\n| rename instance as Instanz",
                "enableSmartSources": true
            }
        },
        "ds_esx": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.vmware.cpu_pct\", \"sakh.vmware.datastore_latency_ms\") BY metric_name host cluster span=5m\n| eval series=host.\" \".if(metric_name=\"sakh.vmware.cpu_pct\", \"CPU %\", \"DS ms\") | timechart span=5m avg(v) by series limit=0",
                "enableSmartSources": true
            }
        },
        "ds_srv_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_srv",
                "query": "| stats latest(v) as v by host application os_family metric_name\n| eval m=case(metric_name=\"sakh.server.cpu_pct\", \"CPU %\", metric_name=\"sakh.server.mem_pct\", \"RAM %\", metric_name=\"sakh.server.fs_data_used_pct\", \"/data %\", metric_name=\"sakh.server.iowait_pct\", \"IO-Wait %\", true(), \"C: frei %\"), v=round(v, 1), key=host.\"|\".application.\"|\".os_family\n| chart first(v) over key by m\n| eval f=split(key, \"|\"), Server=mvindex(f, 0), Anwendung=mvindex(f, 1), OS=mvindex(f, 2) | fields - key f | table Server Anwendung OS *"
            }
        },
        "ds_backup": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:backup\" type!=\"repository\" earliest=-24h\n| stats latest(status) as Status latest(duration_s) as Dauer latest(size_gb) as GB latest(end) as e latest(message) as Meldung by job host\n| eval Ende=strftime(e, \"%d.%m. %H:%M\"), Dauer=round(Dauer / 60, 0).\" min\" | eval s=case(Status=\"Failed\", 0, Status=\"Warning\", 1, true(), 2) | sort s job | fields - e s\n| rename job as Job host as Server",
                "enableSmartSources": true
            }
        },
        "ds_winevents": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"WinEventLog\" (Type=Error OR Type=Warning OR EventCode=4625 OR EventCode=4740)\n| stats count as Anzahl latest(_time) as t latest(Message) as Meldung by ComputerName EventCode Type\n| eval Zeit=strftime(t, \"%H:%M:%S\"), ComputerName=replace(ComputerName, \"\\\\.sakh\\\\.local$\", \"\") | sort - Anzahl | head 20 | table Zeit ComputerName Type EventCode Anzahl Meldung\n| rename ComputerName as Server Type as Typ EventCode as \"Event-ID\"",
                "enableSmartSources": true
            }
        },
        "ds_linux": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"syslog\" (\"error\" OR \"No space\" OR \"ORA-\" OR \"Failed password\" OR \"warning\")\n| rex \"^\\\\w+\\\\s+\\\\d+ [\\\\d:]+ (?<srv>\\\\S+) (?<proc>[^:]+): (?<msg>.*)$\"\n| eval Zeit=strftime(_time, \"%d.%m. %H:%M:%S\") | table Zeit srv proc msg | rename srv as Server proc as Prozess msg as Meldung | head 40",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_care.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_beds",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_diag": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_diag.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_lab",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_medtech": {
            "type": "splunk.image",
