                    }
                }
            ]
        },
        "viz_nav_it": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_it_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_nav_security": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_security.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_security",
                        "tokens": [],
