                    }
                }
            ]
        },
        "viz_sub_kis_servers": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/sub_kis_servers_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_sub_kis_integration": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/sub_kis_integration.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_integration",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_sub_kis_cmdb": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/sub_kis_cmdb.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_cmdb",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_cpu"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 80,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 80,
                        "to": 92,
                        "value": "#c98a00"
                    },
                    {
                        "from": 92,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_q"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "ms",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 20,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 20,
                        "to": 60,
                        "value": "#c98a00"
                    },
                    {
                        "from": 60,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_block"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 5,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 5,
                        "to": 20,
                        "value": "#c98a00"
                    },
                    {
                        "from": 20,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_lag"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "s",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 30,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 30,
                        "to": 60,
                        "value": "#c98a00"
                    },
                    {
                        "from": 60,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_esx"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 70,
                        "to": 85,
                        "value": "#c98a00"
                    },
                    {
                        "from": 85,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_bkp"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#c98a00"
                    },
                    {
                        "from": 3,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_07": {
            "type": "kis_klinik.heat_timeline",
            "dataSources": {
                "primary": "ds_heat_cpu"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 70,
                "crit": 85,
                "unit": "%",
                "maxSeries": 40,
                "decimals": 0,
                "drilldownToken": "host"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "host",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_08": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_host"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "yAxisMin": 0,
                "yAxisMax": 100,
                "lineWidth": 2
            }
        },
        "viz_09": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_fs"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "yAxisMax": 100,
                "lineWidth": 2
            }
        },
        "viz_10": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_srv_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#e9eef4",
                    "rowColors": "#13294b",
                    "headerColor": "#5b6878"
                },
                "columnFormat": {
                    "CPU %": {
                        "rowBackgroundColors": "> table | seriesByName(\"CPU %\") | rangeValue(range_2)"
                    },
                    "/data %": {
                        "rowBackgroundColors": "> table | seriesByName(\"/data %\") | rangeValue(range_3)"
                    },
                    "RAM %": {
                        "rowBackgroundColors": "> table | seriesByName(\"RAM %\") | rangeValue(range_4)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#ffffff",
                    "#f5f7fa"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Degraded",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "Healthy",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "critical",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "high",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "error",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "warning",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "medium",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "stopped",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "failed",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "running",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "success",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "good",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "normal",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "Reachable",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "kritisch",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "voll",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "gestoppt",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Gesperrt",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Offline",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Failed",
                        "value": "#f9dde1"
